"use client";

import React, { useState } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { Wallet, Lock, Mail, ArrowRight, Eye, EyeOff, UserCheck, AlertCircle } from "lucide-react";

export default function LoginPage() {
  const router = useRouter();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");
    setLoading(true);

    try {
      const res = await fetch("/api/auth/login", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email: email.trim(), password })
      });

      const data = await res.json();
      if (!res.ok) {
        throw new Error(data.error || "Failed to log in. Please check your credentials.");
      }

      router.push("/dashboard");
    } catch (err: any) {
      setError(err.message || "An unexpected error occurred.");
    } finally {
      setLoading(false);
    }
  };

  const loginDemoAccount = async () => {
    setEmail("alex@pesapilot.ke");
    setPassword("PilotDemo2026!");
    setError("");
    setLoading(true);

    try {
      const res = await fetch("/api/auth/login", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email: "alex@pesapilot.ke", password: "PilotDemo2026!" })
      });

      if (!res.ok) {
        localStorage.setItem("pesapilot_demo_session", JSON.stringify({ email: "alex@pesapilot.ke", name: "Alex Kiprono" }));
      }
      router.push("/dashboard");
    } catch {
      localStorage.setItem("pesapilot_demo_session", JSON.stringify({ email: "alex@pesapilot.ke", name: "Alex Kiprono" }));
      router.push("/dashboard");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{
      minHeight: "100vh",
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      padding: "24px",
      backgroundColor: "#F8FAFC"
    }}>
      <div style={{
        width: "100%",
        maxWidth: 880,
        backgroundColor: "#FFFFFF",
        borderRadius: 16,
        border: "1px solid #E2E8F0",
        boxShadow: "0 10px 25px -5px rgba(0, 0, 0, 0.05), 0 8px 10px -6px rgba(0, 0, 0, 0.03)",
        overflow: "hidden",
        display: "grid",
        gridTemplateColumns: "repeat(auto-fit, minmax(340px, 1fr))"
      }}>
        {/* Left Side: Real Image Feature Panel */}
        <div style={{
          position: "relative",
          backgroundColor: "#F1F5F9",
          minHeight: 380,
          display: "flex",
          flexDirection: "column",
          justifyContent: "space-between",
          padding: 32,
          overflow: "hidden"
        }}>
          {/* Background image from app/images */}
          <img
            src="/images/student-phone.jpg"
            alt="Student using phone for finance"
            style={{
              position: "absolute",
              inset: 0,
              width: "100%",
              height: "100%",
              objectFit: "cover",
              filter: "brightness(0.9)"
            }}
          />

          {/* Subtle gradient overlay to make text ultra-legible */}
          <div style={{
            position: "absolute",
            inset: 0,
            background: "linear-gradient(to bottom, rgba(15, 23, 42, 0.2) 0%, rgba(15, 23, 42, 0.85) 100%)"
          }} />

          {/* Top Brand on Image */}
          <div style={{ position: "relative", zIndex: 2 }}>
            <Link href="/" style={{ display: "inline-flex", alignItems: "center", gap: 8, textDecoration: "none" }}>
              <div style={{
                width: 32,
                height: 32,
                borderRadius: 8,
                backgroundColor: "#059669",
                display: "flex",
                alignItems: "center",
                justifyContent: "center"
              }}>
                <Wallet size={16} color="#FFFFFF" strokeWidth={2.2} />
              </div>
              <span style={{ fontSize: 18, fontWeight: 800, color: "#FFFFFF" }}>
                Pesa<span style={{ color: "#34D399" }}>Pilot</span>
              </span>
            </Link>
          </div>

          {/* Bottom Quote on Image */}
          <div style={{ position: "relative", zIndex: 2, color: "#FFFFFF" }}>
            <p style={{ fontSize: 15, fontWeight: 500, lineHeight: 1.5, color: "#F1F5F9" }}>
              “Peace of mind starts when you know your rent is locked and your daily matatu fare is covered.”
            </p>
            <span style={{ fontSize: 12, color: "#A7F3D0", marginTop: 6, display: "block" }}>
              Alex Kiprono · UoN Campus Pilot
            </span>
          </div>
        </div>

        {/* Right Side: Clean Formal Form */}
        <div style={{ padding: "36px 32px" }}>
          <div style={{ marginBottom: 20 }}>
            <h2 style={{ fontSize: 22, fontWeight: 800, color: "#0F172A" }}>Sign In to Cockpit</h2>
            <p style={{ fontSize: 13, color: "#64748B", marginTop: 4 }}>
              Enter your student credentials or use 1-click demo access.
            </p>
          </div>

          {/* 1-Click Demo Shortcut */}
          <div style={{
            backgroundColor: "#F0FDF4",
            border: "1px solid #BBF7D0",
            borderRadius: 8,
            padding: "10px 14px",
            marginBottom: 20,
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center"
          }}>
            <div>
              <div style={{ fontSize: 11, fontWeight: 700, color: "#166534" }}>QUICK DEMO STUDENT</div>
              <div style={{ fontSize: 11, color: "#15803D" }}>Alex Kiprono (UoN Student)</div>
            </div>
            <button
              type="button"
              onClick={loginDemoAccount}
              className="btn-primary btn-sm"
              style={{ fontSize: 12 }}
            >
              <UserCheck size={14} />
              1-Click Demo
            </button>
          </div>

          {error && (
            <div style={{
              backgroundColor: "#FFF1F2",
              border: "1px solid #FECDD3",
              borderRadius: 8,
              padding: "10px 12px",
              color: "#9F1239",
              fontSize: 13,
              marginBottom: 16,
              display: "flex",
              alignItems: "center",
              gap: 8
            }}>
              <AlertCircle size={15} color="#E11D48" />
              <span>{error}</span>
            </div>
          )}

          <form onSubmit={handleLogin} style={{ display: "grid", gap: 14 }}>
            <div>
              <label style={{ display: "block", fontSize: 13, color: "#334155", marginBottom: 5, fontWeight: 500 }}>
                Email address
              </label>
              <div style={{ position: "relative" }}>
                <Mail size={15} color="#94A3B8" style={{ position: "absolute", left: 12, top: "50%", transform: "translateY(-50%)" }} />
                <input
                  type="email"
                  required
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  placeholder="student@university.ac.ke"
                  style={{ paddingLeft: 36, fontSize: 13 }}
                />
              </div>
            </div>

            <div>
              <label style={{ display: "block", fontSize: 13, color: "#334155", marginBottom: 5, fontWeight: 500 }}>
                Password
              </label>
              <div style={{ position: "relative" }}>
                <Lock size={15} color="#94A3B8" style={{ position: "absolute", left: 12, top: "50%", transform: "translateY(-50%)" }} />
                <input
                  type={showPassword ? "text" : "password"}
                  required
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  placeholder="••••••••••••"
                  style={{ paddingLeft: 36, paddingRight: 40, fontSize: 13 }}
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  style={{
                    position: "absolute",
                    right: 10,
                    top: "50%",
                    transform: "translateY(-50%)",
                    color: "#94A3B8",
                    padding: 4
                  }}
                >
                  {showPassword ? <EyeOff size={15} /> : <Eye size={15} />}
                </button>
              </div>
            </div>

            <button
              type="submit"
              disabled={loading}
              className="btn-primary"
              style={{ width: "100%", padding: "10px", marginTop: 4 }}
            >
              {loading ? "Signing In..." : "Open Cockpit"}
              {!loading && <ArrowRight size={15} />}
            </button>
          </form>

          <div style={{
            marginTop: 20,
            paddingTop: 16,
            borderTop: "1px solid #E2E8F0",
            textAlign: "center",
            fontSize: 13,
            color: "#64748B"
          }}>
            New to PesaPilot?{" "}
            <Link href="/register" style={{ color: "#059669", fontWeight: 600 }}>
              Create an account
            </Link>
          </div>

          <div style={{ textAlign: "center", marginTop: 12 }}>
            <Link href="/" style={{ fontSize: 12, color: "#94A3B8" }}>
              ← Return to homepage
            </Link>
          </div>
        </div>
      </div>
    </div>
  );
}
